MAXBOOKINGS = 128
MAXLINKS = 128
MAXENVTOTAL = 2048
MAXPARTICIPANTS = 32
MINPARTICIPANTS = 2

ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z')


class Invalid(Exception):
    """Raised when a command fails JSON/schema validation."""


def _int(x):
    if type(x) is not int:
        raise Invalid
    return x


def _bool(x):
    if type(x) is not bool:
        raise Invalid
    return x


def _id(x):
    if not isinstance(x, str):
        raise Invalid
    if ID_RE.match(x) is None:
        raise Invalid
    return x


def _tick(x):
    v = _int(x)
    if v < 0 or v > MAXT:
        raise Invalid
    return v


def _rev(x):
    v = _int(x)
    if v < 0 or v > MAXREV:
        raise Invalid
    return v


def _amount(x):
    v = _int(x)
    if v < 0 or v > MAXT:
        raise Invalid
    return v


def _node(x):
    v = _int(x)
    if v < 0 or v > MAXNODE:
        raise Invalid
    return v


def _linkref(x):
    v = _int(x)
    if v < 0 or v > MAXLINK:
        raise Invalid
    return v


def _list(x):
    if not isinstance(x, list):
        raise Invalid
    return x


def _obj(x, fields):
    if not isinstance(x, dict):
        raise Invalid
    if set(x.keys()) != set(fields):
        raise Invalid
    return x


def window(x):
    w = _list(x)
    if len(w) != 2:
        raise Invalid
    s = _tick(w[0])
    e = _tick(w[1])
    if not (0 <= s < e <= MAXT):
        raise Invalid
    return (s, e)


def envelope(x, max_pairs=MAXENVPairs):
    env = _list(x)
    if len(env) > max_pairs:
        raise Invalid
    out = {}
    for pair in env:
        p = _list(pair)
        if len(p) != 2:
            raise Invalid
        l = _linkref(p[0])
        rate = _int(p[1])
        if rate < 1 or rate > MAXT:
            raise Invalid
        if l in out:
            raise Invalid
        out[l] = rate
    return out


def participants(x):
    ps = _list(x)
    if len(ps) < MINPARTICIPANTS or len(ps) > MAXPARTICIPANTS:
        raise Invalid
    out = {}
    total = 0
    for pair in ps:
        p = _list(pair)
        if len(p) != 2:
            raise Invalid
        v = _node(p[0])
        r = _amount(p[1])
        if v in out:
            raise Invalid
        out[v] = r
        total += r
    if total <= 0:
        raise Invalid
    return out


def parse_command(raw):
    """Validate one decoded JSON value; return ('about',) or (op, payload)."""
    if type(raw) is not dict:
        raise Invalid
    op = raw.get('op')
    if not isinstance(op, str):
        raise Invalid
    if op == 'about':
        _obj(raw, ('op',))
        return ('about',)
    if op == 'load':
        _obj(raw, ('op', 'n', 'links', 'bookings'))
        n = _int(raw['n'])
        if n < 2 or n > 48:
            raise Invalid
        links = _list(raw['links'])
        if len(links) > MAXLINKS:
            raise Invalid
        outlinks = []
        seen = set()
        for lk in links:
            p = _list(lk)
            if len(p) != 3:
                raise Invalid
            u = _node(p[0])
            v = _node(p[1])
            cap = _amount(p[2])
            if u == v or u >= n or v >= n:
                raise Invalid
            key = (u, v) if u < v else (v, u)
            if key in seen:
                raise Invalid
            seen.add(key)
            outlinks.append((u, v, cap))
        bookings = _list(raw['bookings'])
        if len(bookings) > MAXBOOKINGS:
            raise Invalid
        outbook = []
        seenids = set()
        totalenv = 0
        for b in bookings:
            _obj(b, ('id', 'owner', 'window', 'envelope'))
            bid = _id(b['id'])
            owner = _id(b['owner'])
            w = window(b['window'])
            env = envelope(b['envelope'])
            if bid in seenids:
                raise Invalid
            seenids.add(bid)
            totalenv += len(env)
            if totalenv > MAXENVTOTAL:
                raise Invalid
            outbook.append((bid, owner, w, env))
        return ('load', n, outlinks, outbook)
    if op == 'audit':
        _obj(raw, ('op', 'at'))
        at = _list(raw['at'])
        if len(at) > 8:
            raise Invalid
        ticks = [_tick(t) for t in at]
        return ('audit', ticks)
    if op == 'advance':
        _obj(raw, ('op', 'time'))
        t = _tick(raw['time'])
        return ('advance', t)
    if op == 'edit':
        _obj(raw, ('op', 'rev', 'changes', 'force'))
        r = _rev(raw['rev'])
        changes = _list(raw['changes'])
        if len(changes) > MAXENVPairs:
            raise Invalid
        out = []
        seen = set()
        for ch in changes:
            p = _list(ch)
            if len(p) != 2:
                raise Invalid
            l = _linkref(p[0])
            cap = _amount(p[1])
            if l in seen:
                raise Invalid
            seen.add(l)
            out.append((l, cap))
        force = _bool(raw['force'])
        return ('edit', r, out, force)
    if op == 'prepare':
        _obj(raw, ('op', 'id', 'owner', 'window', 'period', 'participants', 'envelope', 'rev'))
        pid = _id(raw['id'])
        owner = _id(raw['owner'])
        w = window(raw['window'])
        period = _int(raw['period'])
        if period < 1 or period > MAXPERIOD:
            raise Invalid
        parts = participants(raw['participants'])
        env = envelope(raw['envelope'])
        r = _rev(raw['rev'])
        return ('prepare', pid, owner, w, period, parts, env, r)
    if op == 'commit':
        _obj(raw, ('op', 'id', 'owner', 'rev'))
        return ('commit', _id(raw['id']), _id(raw['owner']), _rev(raw['rev']))
    if op == 'cancel':
        _obj(raw, ('op', 'id', 'owner', 'rev'))
        return ('cancel', _id(raw['id']), _id(raw['owner']), _rev(raw['rev']))
    raise Invalid
