def min_arborescence(m, edges, root):
    """Chu-Liu/Edmonds: edges = list of (u, v, cost); returns (parent list) or None."""
    INF = float('inf')
    edges = [(u, v, c) for (u, v, c) in edges if u != v and c < INF]
