# ---------------------------------------------------------------- witnesses

def capacity_witness(cap, leases, now, s, e, env):
    """Return (link, t, used, cap) with used(l,t)+b_l > cap(l), s<=t<e, else None."""
    cand = set()
    cand.add(s)
    for lease in leases.values():
        if lease.dead:
            continue
        if s < lease.s < e:
            cand.add(lease.s)
        if s < lease.e < e:
            cand.add(lease.e)
    order = sorted(cand)
    for l in sorted(env):
        b = env[l]
        for t in order:
            used = 0
            for lease in leases.values():
                if lease.dead:
                    continue
                if lease.s <= t < lease.e:
                    used += lease.env.get(l, 0)
            if used + b > cap[l]:
                return (l, t, used + b, cap[l])
    return None


class Dinic(object):
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add(self, u, v, c):
        self.adj[u].append([v, c, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def maxflow(self, s, t):
        flow = 0
        n = self.n
        INF = float('inf')
        while True:
            level = [-1] * n
            level[s] = 0
            queue = [s]
            for u in queue:
                for e in self.adj[u]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[u] + 1
                        queue.append(e[0])
            if level[t] < 0:
                return flow
            it = [0] * n

            def dfs(u, f):
                if u == t:
                    return f
                while it[u] < len(self.adj[u]):
                    e = self.adj[u][it[u]]
                    if e[1] > 0 and level[e[0]] == level[u] + 1:
                        d = dfs(e[0], f if f < e[1] else e[1])
                        if d > 0:
                            e[1] -= d
                            self.adj[e[0]][e[2]][1] += d
                            return d
                    it[u] += 1
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

    def source_side(self, s):
        seen = set()
        stack = [s]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            for e in self.adj[u]:
                if e[1] > 0:
                    stack.append(e[0])
        return seen


def cut_witness(links, env, period, parts):
    """Deficient cut S: sum(period*b_l over crossing links) < sum(r_v, v in S).

    S contains at least one participant but not all; returns sorted list or None.
    """
    n = 0
    for (u, v, c) in links:
        n = max(n, u + 1, v + 1)
    for v in parts:
        n = max(n, v + 1)
    D = sum(parts.values())
    sigma = n
    tau = n + 1
    total_cap = 0
    for idx, (a, b, c) in enumerate(links):
        total_cap += period * env.get(idx, 0)
    INF = D + total_cap + 1
    participants = sorted(parts)
    for u in participants:
        for w in participants:
            if u == w:
                continue
            g = Dinic(n + 2)
            for idx, (a, b, c) in enumerate(links):
                cp = period * env.get(idx, 0)
                if cp > 0:
                    g.add(a, b, cp)
                    g.add(b, a, cp)
            for v in participants:
                if parts[v] > 0:
                    g.add(sigma, v, parts[v])
            g.add(sigma, u, INF)
            g.add(w, tau, INF)
            g.maxflow(sigma, tau)
            side = g.source_side(sigma)
            if u not in side or w in side:
                continue
            crossing = 0
            for idx, (a, b, c) in enumerate(links):
                if (a in side) != (b in side):
                    crossing += period * env.get(idx, 0)
            demand = sum(parts[v] for v in participants if v in side)
            if crossing < demand:
                return sorted(x for x in range(n) if x in side)
    return None


# ------------------------------------------------------------- plan builder

class BuildFailure(Exception):
    pass


class Graph(object):
    """Undirected loaded graph with per-direction budgets c_l = period*b_l."""

    def __init__(self, links, env, period):
        self.nlink = len(links)
        self.ends = [(u, v) for (u, v, c) in links]
        self.cap = [period * env.get(i, 0) for i in range(self.nlink)]
        nv = 0
        for (u, v) in self.ends:
            nv = max(nv, u + 1, v + 1)
        self.nv = nv
        self.adj = [[] for _ in range(nv)]
        for i, (u, v) in enumerate(self.ends):
            self.adj[u].append((v, i, 0))
            self.adj[v].append((u, i, 1))

    def arc_cost(self, a, residual, price):
        return price(residual[a[1] * 2 + a[2]])

    def dijkstra(self, src, residual, price, allowed):
        """Shortest walks from src to every allowed vertex.

        allowed(x) tells whether vertex x may appear as an interior/endpoint;
        the walk may only traverse vertices with allowed() true, plus src.
        Returns (cost dict, prev dict) with prev[v] = (u, link, dir).
        """
        import heapq
        INF = float('inf')
        cost = {src: 0.0}
        prev = {}
        done = set()
        heap = [(0.0, src)]
        while heap:
            (c, u) = heapq.heappop(heap)
            if u in done:
                continue
            done.add(u)
            for (v, l, d) in self.adj[u]:
                if v != src and not allowed(v):
                    continue
                idx = l * 2 + d
                pc = price(residual[idx])
                if pc == INF:
                    continue
                nc = c + pc
                if nc < cost.get(v, INF):
                    cost[v] = nc
                    prev[v] = (u, l, d)
                    heapq.heappush(heap, (nc, v))
        return cost, prev

    def walk_to(self, prev, y):
        walk = []
        cur = y
        while cur in prev:
            (u, l, d) = prev[cur]
            walk.append((l, d))
            cur = u
        walk.reverse()
        return walk


def make_price(kind):
    if kind == 'inv':
        return lambda r: (float('inf') if r <= 0 else 1.0 / (r + 1))
    if kind == 'unit':
        return lambda r: (float('inf') if r <= 0 else 1.0)
    if kind == 'invsq':
        return lambda r: (float('inf') if r <= 0 else 1.0 / (r + 1) ** 2)
    return lambda r: (float('inf') if r <= 0 else 1.0 / (r + 1))


class Builder(object):
    def __init__(self, graph, participants, demands):
        self.g = graph
        self.C = sorted(participants)
        self.dem = dict(demands)
        self.residual = list(graph.cap)
        self.trees = []      # [root, count, [(x,y), ...]]
        self.routes = {}     # (x, y, walktuple) -> count

    def is_part(self, v):
        return v in self.dem

    def paths_from(self, src, price):
        allowed = lambda v: not self.is_part(v)
        cost, prev = self.g.dijkstra(src, self.residual, price, allowed)
        return cost, prev

    def tree_walks(self, edges, prevmap):
        out = []
        for (x, y) in edges:
            walk = self.g.walk_to(prevmap[x], y)
            if not walk:
                return None
            out.append(walk)
        return out

    def usage_of(self, walks):
        usage = {}
        for walk in walks:
            for a in walk:
                k = a[0] * 2 + a[1]
                usage[k] = usage.get(k, 0) + 1
        return usage

    def bottleneck(self, usage, remaining):
        w = remaining
        for k, cnt in usage.items():
            q = self.residual[k] // cnt
            if q < w:
                w = q
        return w

    def push(self, walks, w, edges):
        for (walk, (x, y)) in zip(walks, edges):
            for a in walk:
                self.residual[a[0] * 2 + a[1]] -= w
            key = (x, y, tuple(walk))
            self.routes[key] = self.routes.get(key, 0) + w

    def candidates(self, root, price):
        """Generate candidate out-arborescences rooted at root: (edges, walks, score)."""
        cost = {}
        prev = {}
        for x in self.C:
            c, p = self.paths_from(x, price)
            cost[x] = c
            prev[x] = p
        out = []

        def add(order):
            edges = []
            walks = []
            ok = True
            for i in range(len(order) - 1):
                x, y = order[i], order[i + 1]
                if y not in cost[x]:
                    ok = False
                    break
                edges.append((x, y))
                walks.append(self.g.walk_to(prev[x], y))
            if ok:
                out.append((edges, walks))

        # chain candidates in a few orders
        for fn in (self.order_nearest, self.order_far, self.order_id):
            order = fn(root, cost)
            if order is not None:
                add(order)
                add([root] + list(reversed(order[1:])))
        # star at root
        edges = []
        walks = []
        ok = True
        for y in self.C:
            if y == root:
                continue
            if y not in cost[root]:
                ok = False
                break
            edges.append((root, y))
            walks.append(self.g.walk_to(prev[root], y))
        if ok:
            out.append((edges, walks))
        # prim-style growth (min cost to connect a new participant)
        edges, walks = self.prim(root, cost, prev)
        if edges is not None:
            out.append((edges, walks))
        return out

    def order_nearest(self, root, cost):
        order = [root]
        rest = [y for y in self.C if y != root]
        cur = root
        while rest:
            best = None
            bestc = None
            for y in rest:
                if y in cost[cur]:
                    c = cost[cur][y]
                    if bestc is None or c < bestc or (c == bestc and y < best):
                        bestc = c
                        best = y
            if best is None:
                return None
            order.append(best)
            rest.remove(best)
            cur = best
        return order

    def order_far(self, root, cost):
        order = [root]
        rest = [y for y in self.C if y != root]
        cur = root
        while rest:
            best = None
            bestc = None
            for y in rest:
                if y in cost[cur]:
                    c = cost[cur][y]
                    if bestc is None or c > bestc or (c == bestc and y < best):
                        bestc = c
                        best = y
            if best is None:
                return None
            order.append(best)
            rest.remove(best)
            cur = best
        return order

    def order_id(self, root, cost):
        order = [root] + [y for y in self.C if y != root]
        for i in range(len(order) - 1):
            if order[i + 1] not in cost[order[i]]:
                return None
        return order

    def prim(self, root, cost, prev):
        inside = {root}
        edges = []
        walks = []
        while len(inside) < len(self.C):
            best = None
            bestc = None
            bestx = None
            for x in sorted(inside):
                for y in self.C:
                    if y in inside or y not in cost[x]:
                        continue
                    c = cost[x][y]
                    if bestc is None or c < bestc or (c == bestc and (x, y) < (bestx, best)):
                        bestc = c
                        best = y
                        bestx = x
            if best is None:
                return None, None
            edges.append((bestx, best))
            walks.append(self.g.walk_to(prev[bestx], best))
            inside.add(best)
        return edges, walks

    def build(self, order, price_kind):
        price = make_price(price_kind)
        for root in order:
            remaining = self.dem[root]
            guard = 0
            while remaining > 0:
                guard += 1
                if guard > 4000:
                    return False
                cands = self.candidates(root, price)
                best = None
                for (edges, walks) in cands:
                    usage = self.usage_of(walks)
                    w = self.bottleneck(usage, remaining)
                    if w <= 0:
                        continue
                    score = (w, -sum(len(wk) for wk in walks))
                    if best is None or score > best[0]:
                        best = (score, edges, walks, w)
                if best is None:
                    return False
                (_, edges, walks, w) = best
                self.push(walks, w, edges)
                self.trees.append([root, w, edges])
                remaining -= w
        return True


class RecipeBook(object):
    def __init__(self):
        self.nodes = []
        self.memo = {}

    def intern(self, node):
        key = tuple(node)
        if key in self.memo:
            return self.memo[key]
        idx = len(self.nodes)
        self.nodes.append(node)
        self.memo[key] = idx
        return idx

    def walk_recipe(self, walk):
        if not walk:
            return None
        # binary split memoized on the exact segment tuple
        def build(seg):
            key = ('seg', seg)
            if key in self.memo:
                return self.memo[key]
            if len(seg) == 1:
                l, d = seg[0]
                nid = self.intern([0, l, d])
            else:
                m = len(seg) // 2
                left = build(seg[:m])
                right = build(seg[m:])
                nid = self.intern([1, left, right])
            self.memo[key] = nid
            return nid
        return build(tuple(walk))


def verify_plan(links, env, period, parts, plan):
    try:
        trees = plan['trees']
        routes = plan['routes']
        recipes = plan['recipes']
        if len(trees) > 8192 or len(routes) > 32768 or len(recipes) > 65536:
            return False
        C = set(parts)
        D = sum(parts.values())
        L = {}
        sums = {}
        for rec in trees:
            if not isinstance(rec, list) or len(rec) != 3:
                return False
            root, count, edges = rec
            if root not in C or type(count) is not int or count < 1 or count > D:
                return False
            if len(edges) != len(C) - 1:
                return False
            eset = set()
            indeg = {v: 0 for v in C}
            for e in edges:
                if not isinstance(e, list) or len(e) != 2:
                    return False
                x, y = e
                if x not in C or y not in C or x == y:
                    return False
                if (x, y) in eset:
                    return False
                eset.add((x, y))
                indeg[y] += 1
            for v in C:
                want = 0 if v == root else 1
                if indeg[v] != want:
                    return False
            # reachability from root
            seen = {root}
            changed = True
            while changed:
                changed = False
                for (x, y) in eset:
                    if x in seen and y not in seen:
                        seen.add(y)
                        changed = True
            if seen != C:
                return False
            sums[root] = sums.get(root, 0) + count
            for (x, y) in eset:
                L[(x, y)] = L.get((x, y), 0) + count
        for v in C:
            if sums.get(v, 0) != parts[v]:
                return False
        # recipes
        expanded = []

        def expand(i, seen):
            if i in seen:
                return None
            node = recipes[i]
            if node[0] == 0:
                return [(node[1], node[2])]
            if node[0] != 1 or len(node) != 3:
                return None
            a = expand(node[1], seen | {i})
            b = expand(node[2], seen | {i})
            if a is None or b is None:
                return None
            return a + b

        for i in range(len(recipes)):
            node = recipes[i]
            if not isinstance(node, list):
                return False
            if node and node[0] == 0:
                if len(node) != 3:
                    return False
                if type(node[1]) is not int or type(node[2]) is not int:
                    return False
                l, d = node[1], node[2]
                if not (0 <= l < len(links)) or d not in (0, 1):
                    return False
            elif node and node[0] == 1:
                if len(node) != 3:
                    return False
                a, b = node[1], node[2]
                if type(a) is not int or type(b) is not int:
                    return False
                if not (0 <= a < len(recipes)) or not (0 <= b < len(recipes)):
                    return False
            else:
                return False
        acyc = [None] * len(recipes)

        def dag_ok(i):
            st = [i]
            while st:
                x = st.pop()
                if acyc[x] == 1:
                    continue
                if acyc[x] == 0:
                    return False
                acyc[x] = 0
                node = recipes[x]
