def compile_plan(links, env, period, parts):
    """Build a PLAN; raises BuildFailure only if no strategy produced one."""
    g = Graph(links, env, period)
    dem = dict(parts)
    orders = []
    base = sorted(dem)
    orders.append(sorted(base, key=lambda v: (-dem[v], v)))
    orders.append(sorted(base, key=lambda v: (dem[v], v)))
    orders.append(base)
    orders.append(sorted(base, key=lambda v: -dem[v]))
    seen = set()
    best = None
    for price_kind in ('inv', 'unit', 'invsq'):
        for order in orders:
            key = (price_kind, tuple(order))
            if key in seen:
                continue
            seen.add(key)
            b = Builder(g, base, dem)
            if not b.build(order, price_kind):
                continue
            plan = assemble(links, env, period, parts, b)
            if plan is None:
                continue
            if verify_plan(links, env, period, parts, plan):
                return plan
            if best is None:
                best = plan
    if best is not None:
        return best
    raise BuildFailure('no plan found')


def assemble(links, env, period, parts, b):
    book = RecipeBook()
    routes = []
    for ((x, y, walk), count) in sorted(b.routes.items()):
        if count <= 0:
            return None
        rid = book.walk_recipe(walk)
        routes.append([x, y, count, rid])
    trees = []
    for (root, w, edges) in b.trees:
        trees.append([root, w, [[x, y] for (x, y) in edges]])
    if len(trees) > 8192 or len(routes) > 32768 or len(book.nodes) > 65536:
        return None
    return {'trees': trees, 'routes': routes, 'recipes': book.nodes}
