def check_reply(cmd, rep, state):
    st = rep.get('status')
    # structural field checks
    ok_fields = {
        'ok': None,  # depends on op
    }
    op = cmd.get('op') if isinstance(cmd, dict) else None
    if st == 'invalid':
        return set(rep.keys()) == {'status'}
    if st == 'stale':
        return set(rep.keys()) == {'status', 'rev'}
    if st == 'replay':
        return set(rep.keys()) == {'status','id','rev','base_rev','outcome'} and rep['outcome'] in ('prepared','denied')
    if st == 'blocked':
        if set(rep.keys()) != {'status','rev','link','time','used','capacity'}: return False
        # witness: used > capacity at link/time
        return rep['used'] > rep['capacity']
    if st == 'denied':
        if rep.get('kind') == 'capacity':
            if set(rep.keys()) != {'status','id','rev','kind','link','time','used','capacity'}: return False
            return rep['used'] > rep['capacity']
        if rep.get('kind') == 'cut':
            if set(rep.keys()) != {'status','id','rev','kind','cut'}: return False
            S = set(rep['cut'])
            if len(S) != len(rep['cut']): return False
            # validate strict inequality against the prepare request
            return state is not None and check_cut(cmd, rep['cut'])
        return False
    if st == 'prepared':
        if set(rep.keys()) != {'status','id','rev','plan'}: return False
        return check_plan(cmd, rep['plan'])
    if st == 'error':
        return set(rep.keys()) == {'status','code','rev'} and rep['code'] in (
            'NOT_LOADED','ALREADY_LOADED','TIME','REFERENCE','WINDOW','CONFLICT',
            'MISSING','OWNER','GONE','DENIED')
    if st == 'ok':
        if op == 'about':
            return rep == {'status':'ok','protocol':'forest-controller/3'}
        if op == 'load':
            return set(rep.keys()) == {'status','rev','now'}
        if op == 'audit':
