        if op == 'advance':
            return set(rep.keys()) == {'status','rev','now','expired'}
        if op == 'edit':
            return set(rep.keys()) == {'status','rev','cancelled'}
        if op == 'commit':
            return set(rep.keys()) == {'status','id','rev','replay'} and isinstance(rep['replay'], bool)
        if op == 'cancel':
            return set(rep.keys()) == {'status','rev','released'}
    return False

